import { execute, query, queryOne } from '@/lib/db';
import { newId } from '@/lib/ids';

export interface MessageRow {
  id: string;
  org_id: string;
  sender_user_id: string;
  recipient_user_id: string;
  patient_id: string | null;
  subject: string;
  body: string;
  created_at: Date;
  read_at: Date | null;
}

export async function createMessage(input: {
  orgId: string;
  senderUserId: string;
  recipientUserId: string;
  patientId: string | null;
  subject: string;
  body: string;
}): Promise<string> {
  const id = newId('msg');
  await execute(
    `INSERT INTO messages (id, org_id, sender_user_id, recipient_user_id, patient_id, subject, body)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [id, input.orgId, input.senderUserId, input.recipientUserId, input.patientId, input.subject, input.body],
  );
  return id;
}

/** Inbox listing: no bodies. */
export async function listInbox(userId: string): Promise<Array<{ id: string; subject: string; sender_name: string; created_at: Date; read_at: Date | null }>> {
  return query(
    `SELECT m.id, m.subject, u.display_name AS sender_name, m.created_at, m.read_at
       FROM messages m JOIN users u ON u.id = m.sender_user_id
      WHERE m.recipient_user_id = ?
      ORDER BY m.created_at DESC`,
    [userId],
  );
}

/**
 * Full message with everything around it (sender, recipient, patient), as used by the
 * support console when staff investigate a delivery problem.
 */
export async function findWithContext(messageId: string): Promise<Record<string, unknown> | null> {
  return queryOne(
    `SELECT m.*,
            s.display_name AS sender_name, s.email AS sender_email,
            r.display_name AS recipient_name, r.email AS recipient_email,
            p.first_name AS patient_first_name, p.last_name AS patient_last_name,
            p.mrn AS patient_mrn, p.date_of_birth AS patient_dob, p.reason_for_care AS patient_reason_for_care
       FROM messages m
       JOIN users s ON s.id = m.sender_user_id
       JOIN users r ON r.id = m.recipient_user_id
       LEFT JOIN patients p ON p.id = m.patient_id
      WHERE m.id = ?`,
    [messageId],
  );
}

export async function getMessage(messageId: string): Promise<MessageRow | null> {
  return queryOne<MessageRow>('SELECT * FROM messages WHERE id = ?', [messageId]);
}

export async function markRead(messageId: string): Promise<void> {
  await execute('UPDATE messages SET read_at = UTC_TIMESTAMP(3) WHERE id = ? AND read_at IS NULL', [messageId]);
}
import { z } from 'zod';
import { requireUser, requireRole } from '@/lib/auth';
import { json, readJson, route, HttpError } from '@/lib/http';
import { logger } from '@/lib/logger';
import { audit } from '@/lib/audit';
import { getUser } from '@/repos/users';
import { createMessage, listInbox } from '@/repos/messages';

const SendBody = z.object({
  recipientUserId: z.string().min(1),
  patientId: z.string().min(1).nullable().optional(),
  subject: z.string().min(1).max(200),
  body: z.string().min(1).max(10000),
});

/** Inbox of the signed-in user (no message bodies). */
export const GET = route(async (req) => {
  const user = await requireUser(req);
  const rows = await listInbox(user.id);
  return json({
    messages: rows.map((r) => ({
      id: r.id,
      subject: r.subject,
      from: r.sender_name,
      sentAt: r.created_at,
      read: r.read_at !== null,
    })),
  });
});

/** Sends a secure message to another user of the same practice. */
export const POST = route(async (req) => {
  const user = await requireUser(req);
  requireRole(user, 'practitioner', 'patient');
  const input = SendBody.parse(await readJson(req));

  const recipient = await getUser(input.recipientUserId);
  if (!recipient || recipient.org_id !== user.orgId || recipient.id === user.id) {
    throw new HttpError(403, 'forbidden');
  }

  const id = await createMessage({
    orgId: user.orgId,
    senderUserId: user.id,
    recipientUserId: recipient.id,
    patientId: input.patientId ?? (user.role === 'patient' ? user.patientId : null),
    subject: input.subject,
    body: input.body,
  });
  await audit(user, 'message.send', 'message', id);
  logger.info('message sent', { messageId: id, senderId: user.id, recipientId: recipient.id });
  return json({ id }, 201);
});
import { NextResponse } from 'next/server';
import { ZodError } from 'zod';

export class HttpError extends Error {
  constructor(public readonly status: number, public readonly publicMessage: string) {
    super(publicMessage);
  }
}

export function json(data: unknown, status = 200): NextResponse {
  return NextResponse.json(data, { status });
}

type Handler<C> = (req: Request, ctx: C) => Promise<Response>;

/**
 * Wraps a route handler: known HttpErrors become JSON `{ error }` responses,
 * validation errors become 400, anything else becomes a 500.
 */
export function route<C = unknown>(handler: Handler<C>): Handler<C> {
  return async (req, ctx) => {
    try {
      return await handler(req, ctx);
    } catch (err) {
      if (err instanceof HttpError) return json({ error: err.publicMessage }, err.status);
      if (err instanceof ZodError) return json({ error: 'invalid_request' }, 400);
      return new Response(null, { status: 500 });
    }
  };
}

export async function readJson(req: Request): Promise<unknown> {
  try {
    return await req.json();
  } catch {
    throw new HttpError(400, 'invalid_json');
  }
}
